test("POST /transfers moves store credit and validates input", async () => {
  const post = (token: string, body: unknown) =>
    fetch(`${base}/transfers`, { method: "POST", headers: { ...as(token), "content-type": "application/json" }, body: JSON.stringify(body) });
  const bal = async (id: number) => (await pool.query("select balance_cents from wallets where user_id = $1", [id])).rows[0].balance_cents;
